import hashlib
import os

# Funktion zur Generierung eines zufälligen Salts
def generate_salt(length=32):
    return os.urandom(length).hex()

# Funktion zum Hashen des Passworts mit Salt
def hash_password(password, salt):
    return hashlib.sha256((password + salt).encode()).hexdigest()

# Funktion zum Registrieren eines Benutzers
def register_user(username, password, db_file="users.txt"):
    salt = generate_salt()
    hashed_password = hash_password(password, salt)

    with open(db_file, "a") as f:
        f.write(f"{username}:{hashed_password}:{salt}\n")
    print(f"Benutzer {username} erfolgreich registriert.")

# Funktion zum Überprüfen der Anmeldung
def login_user(username, password, db_file="users.txt"):
    try:
        with open(db_file, "r") as f:
            for line in f:
                stored_username, stored_hash, salt = line.strip().split(":")
                if stored_username == username:
                    # Hash des eingegebenen Passworts mit dem gespeicherten Salt
                    if hash_password(password, salt) == stored_hash:
                        print("Anmeldung erfolgreich!")
                        return True
                    else:
                        print("Falsches Passwort!")
                        return False
        print("Benutzer nicht gefunden!")
        return False
    except FileNotFoundError:
        print("Datenbankdatei nicht gefunden!")
        return False

# Beispielverwendung
if __name__ == "__main__":
    # Registrierung
    register_user("admin", "meinPasswort123")

    # Anmeldung
    login_user("admin", "meinPasswort123")
    login_user("admin", "falschesPasswort")
